5: export default class TestProgress {
6:   constructor() { this.fd = openSync(process.env.ARTROOM_TEST_PROGRESS, "wx", 0o600); }
7:   write(event, details) { writeSync(this.fd, `${JSON.stringify({ event, time: new Date().toISOString(), ...details })}\n`); }
8:   case(event, test) {
9:     this.write(event, { id: test.id, project: test.project.name, file: test.module.moduleId, name: test.fullName,
10:       ...(event !== "case-ready" ? { state: test.result().state } : {}) });
11:   }
12:   onTestRunStart(specifications) { this.write("run-start", { files: specifications.length }); }
13:   onTestCaseReady(test) { this.case("case-ready", test); }
14:   onTestCaseResult(test) { this.case("case-result", test); }
15:   onTestRunEnd(modules, errors, reason) {
16:     // Native incremental callbacks can omit already completed cases. Retain
17:     // the terminal framework state separately from the original event stream.
18:     for (const module of modules) for (const test of module.children.allTests()) this.case("case-final", test);
19:     this.write("run-end", { files: modules.length, unhandledErrors: errors.length, reason });
20:     closeSync(this.fd);
21:   }

